{
    public static class JorgeLuisBorges
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "All things have been given to us for a purpose, and an artist must feel this more intensely. All that happens to us, including our humiliations, our misfortunes, our embarrassments, all is given to us as raw material, as clay, so that we may shape our art.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Our nothingness differs little; it is a trivial and chance circumstance that you should be the reader of these exercises and I their author.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Gibbon observes that in the Arabian book \"par excellence\", in the Koran, there are no camels; I believe if there were any doubt as to the authenticity of the Koran, this absence of camels would be sufficient to prove it is an Arabian work.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I think we Argentines can emulate Mohammed, can believe in the possibility of being Argentine without abounding in local color.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "That one individual should awaken in another memories that belong to still a third is an obvious paradox.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Reading … is an activity subsequent to writing: more resigned, more civil, more intellectual.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The earth we inhabit is an error, an incompetent parody. Mirrors and paternity are abominable because they multiply and affirm it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The universe (which others call the Library) is composed of an indefinite and perhaps infinite number of hexagonal galleries, with vast air shafts between, surrounded by very low railings.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "From these two incontrovertible premises he deduced that the Library is total and that its shelves register all the possible combinations of the twenty-odd orthographical symbols (a number which, though extremely vast, is not infinite).", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There is no combination of characters one can make — dhcmrlchtdj, for example — that the divine Library has not foreseen and that in one or more of its secret tongues does not hide a terrible significance.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There is no syllable one can speak that is not filled with tenderness and terror, that is not, in one of those languages, the mighty name of a god.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "May Heaven exist, even if my place is Hell.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Let heaven exist, though my own place may be in hell. Let me be tortured and battered and annihilated, but let there be one instant, one creature, wherein thy enormous Library may find its justification.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Dictatorships foster oppression, dictatorships foster servitude, dictatorships foster cruelty; more abominable is the fact that they foster idiocy.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "In that Empire, the Art of Cartography attained such Perfection that the map of a single Province occupied the entirety of a City, and the map of the Empire, the entirety of a Province.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "In the Deserts of the West, still today, there are Tattered Ruins of that Map, inhabited by Animals and Beggars; in all the Land there is no other Relic of the Disciplines of Geography.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There is nothing very remarkable about being immortal; with the exception of mankind, all creatures are immortal, for they know nothing of death.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "What is divine, terrible, and incomprehensible is to know oneself immortal.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There are no moral or intellectual merits. Homer composed the Odyssey; if we postulate an infinite period of time, with infinite circumstances and changes, the impossible thing is not to compose the Odyssey, at least once.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "No one is anyone, one single immortal man is all men.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Like Cornelius Agrippa, I am god, I am hero, I am philosopher, I am demon and I am world, which is a tedious way of saying that I do not exist.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Any life, however long and complicated it may be, actually consists of a single moment — the moment when a man knows forever more who he is.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There's no need to build a labyrinth when the entire universe is one.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The minotaur more than justifies the existence of the labyrinth.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "His many years had reduced and polished him the way water smooths and polishes a stone or generations of men polish a proverb.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I would define the baroque as that style that deliberately exhausts (or tries to exhaust) its own possibilities, and that borders on self-caricature.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The baroque is the final stage in all art, when art flaunts and squanders its resources.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is universally held that the unicorn is a supernatural being and of auspicious omen; so say the odes, the annals, the biographies of worthies, and other texts whose authority is unimpeachable.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "We know that a certain animal with a mane is a horse and that a certain animal with horns is a bull. We do not know what the unicorn looks like.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "To die for a religion is easier than to live it absolutely.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Years of solitude had taught him that, in one's memory, all days tend to be the same, but that there is not a day, not even in jail or in the hospital, which does not bring surprises, which is not a translucent network of minimal surprises.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Every novel is an ideal plane inserted into the realm of reality.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The heresies we should fear are those which can be confused with orthodoxy.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Like all those possessing a library, Aurelian was aware that he was guilty of not knowing his in its entirety.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Do you want to see what human eyes have never seen? Look at the moon. Do you want to hear what ears have never heard? Listen to the bird's cry.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Verily I say that God is about to create the world.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Writing is nothing more than a guided dream.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I have sometimes suspected that the only thing that holds no mystery is happiness, because it is its own justification.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "My advanced age has taught me the resignation of being Borges.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Time can't be measured in days the way money is measured in pesos and centavos, because all pesos are equal, while every day, perhaps every hour, is different.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The poverty of yesterday was less squalid than the poverty we purchase with our industry today.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Fortunes were smaller then as well.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "When one confesses to an act, one ceases to be an actor in it and becomes its witness, becomes a man that observes and narrates it and no longer the man that performed it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Being with you and not being with you is the only way I have to measure time.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Truly fine poetry must be read aloud. A good poem does not allow itself to be read in a low voice or silently.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "If we can read it silently, it is not a valid poem: a poem demands pronunciation.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Poetry always remembers that it was an oral art before it was a written art. It remembers that it was first song.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Films are even stranger, for what we are seeing are not disguised people but photographs of disguised people, and yet we believe them while the film is being shown.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The fact is that poetry is not the books in the library . . . Poetry is the encounter of the reader with the book, the discovery of the book.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The aesthetic event is something as evident, as immediate, as indefinable as love, the taste of fruit, of water.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "We feel poetry as we feel the closeness of a woman, or as we feel a mountain or a bay.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "If we feel it immediately, why dilute it with other words, which no doubt will be weaker than our feelings?", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There are people who barely feel poetry, and they are generally dedicated to teaching it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Doubt is one of the names of intelligence.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "As I think of the many myths, there is one that is very harmful, and that is the myth of countries.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I mean, why should I think of myself as being an Argentine, and not a Chilean, and not an Uruguayan.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "All of those myths that we impose on ourselves — and they make for hatred, for war, for enmity — are very harmful.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Well, I suppose in the long run, governments and countries will die out and we'll be just, well, cosmopolitans.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I am not sure that I exist, actually. I am all the writers that I have read, all the people that I have met, all the women that I have loved; all the cities that I have visited, all my ancestors.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I have committed the worst sin that can be committed. I have not been happy.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The man who acquires an encyclopedia does not thereby acquire every line, every paragraph, every page, and every illustration; he acquires the \"possibility\" of becoming familiar with one and another of those things.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The Falklands thing was a fight between two bald men over a comb.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Life itself is a quotation.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "How else can one threaten, other than with death? The interesting, the original thing, would be to threaten someone with immortality.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The mightiest love was granted him Love that does not expect to be loved.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Reality is not always probable, or likely.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "But if you're writing a story, you have to make it as plausible as you can, because if not, the reader's imagination will reject it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I tried mescaline and cocaine in my youth, but I immediately switched to mint candy, which was more stimulating.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I am not interested in drugs if they produce the same effects as alcohol. A drunkard is evidently ridiculous.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I have been drunk some times, and I remember them as horrible experiences for me and everyone else.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I will pause to consider this eternity from which the subsequent ones derive.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Whoever hears me assert that the grey cat playing just now in the yard is the same one that did jumps and tricks there five hundred years ago will think whatever he likes of me, but it is a stranger form of madness to imagine that the present-day cat is fundamentally an entirely different one.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Heaven and hell seem out of proportion to me: the actions of men do not deserve so much.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Censorship is the mother of metaphor.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Life and death have been lacking in my life.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Imprecision is tolerable and verisimilar in literature, because we always tend towards it in life.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The exercise of letters is sometimes linked to the ambition to construct an absolute book, a book of books that includes the others like a Platonic archetype, an object whose virtues are not diminished by the passage of time.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Art always opts for the individual, the concrete; art is not Platonic.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is known that Whistler when asked how long it took him to paint one of his \"nocturnes\" answered: \"All of my life.\"", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "With the same rigor he could have said that all of the centuries that preceded the moment when he painted were necessary.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "From that correct application of the law of causality it follows that the slightest event presupposes the inconceivable universe and, conversely, that the universe needs even the slightest of events.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "We (the indivisible divinity that works in us) have dreamed the world.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "We have dreamed it resistant, mysterious, visible, ubiquitous in space and firm in time, but we have allowed slight, and eternal, bits of the irrational to form part of its architecture so as to know that it is false.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There is a concept which corrupts and upsets all others. I refer not to Evil, whose limited realm is that of ethics; I refer to the infinite.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "He transforms all concepts into incommunicable, solidified objects. To refute him is to become contaminated with unreality.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is venturesome to think that a coordination of words (philosophies are nothing more than that) can resemble the universe very much.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is also venturesome to think that of all these illustrious coordinations, one of them — at least in an infinitesimal way — does not resemble the universe a bit more than the others.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The central problem of novel-writing is causality.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The possibilities of the art of combination are not infinite, but they tend to be frightful.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Hollywood has just enriched this vain museum of horrors: by means of an artistic malignity called dubbing, it proposes monsters that combine the illustrious features of Greta Garbo with the voice of Aldonza Lorenzo.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I owe the discovery of Uqbar to the conjunction of a mirror and an encyclopedia.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Mirrors and copulation are obscene, for they increase the numbers of mankind.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "For one of those gnostics, the visible universe was an illusion or, more precisely, a sophism.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Mirrors and fatherhood are abominable because they multiply it and extend it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "In his lifetime, he suffered from unreality, as do so many Englishmen; once dead, he is not even the ghost he was then.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Who are the inventors of Tlön? The plural is inevitable, because the hypothesis of a lone inventor — an infinite Leibniz laboring away darkly and modestly — has been unanimously discounted.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is conjectured that this brave new world is the work of a secret society of astronomers, biologists, engineers, metaphysicians, poets, chemists, algebraists, moralists, painters, geometers... directed by an obscure man of genius.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Hume noted for all time that Berkeley's arguments did not admit the slightest refutation nor did they cause the slightest conviction.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "This dictum is entirely correct in its application to the earth, but entirely false in Tlön.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The nations of this planet are congenitally idealist.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Their language and the derivations of their language — religion, letters, metaphysics — all presuppose idealism.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The world for them is not a concourse of objects in space; it is a heterogeneous series of independent acts.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is successive and temporal, not spatial.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "One thinker no less brilliant than the heresiarch himself, but in the orthodox tradition, advanced a most daring hypothesis.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "This felicitous supposition declared that there is only one Individual, and that this indivisible Individual is every one of the separate beings in the universe, and that these beings are the instruments and masks of divinity itself.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The geometry of Tlön comprises two somewhat different disciplines: the visual and the tactile.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The latter corresponds to our own geometry and is subordinated to the first.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It is no exaggeration to state that the classic culture of Tlön comprises only one discipline: psychology.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "All others are subordinated to it.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I have said that the men of this planet conceive the universe as a series of mental processes which do not develop in space but successively in time.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The metaphysicians of Tlön do not seek for the truth or even for verisimilitude, but rather for the astounding.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "They judge that metaphysics is a branch of fantastic literature.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "They know that a system is nothing more than the subordination of all aspects of the universe to any one such aspect.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Even the phrase \"all aspects\" is rejectable, for it supposes the impossible addition of the present and of all past moments.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "One of the schools of Tlön goes so far as to negate time; it reasons that the present is indefinite, that the future has no reality other than as a present hope, that the past has no reality other than as a present memory.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Another school declares that all time has already transpired and that our life is only the crepuscular and no doubt falsified an mutilated memory or reflection of an irrecoverable process.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Another, that the history of the universe — and in it our lives and the most tenuous detail of our lives — is the scripture produced by a subordinate god in order to communicate with a demon.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Another, that the universe is comparable to those cryptographs in which not all the symbols are valid and that only what happens every three hundred nights is true.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Another, that while we sleep here, we are awake elsewhere and that in this way every man is two men.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Today, one of the churches of Tlön Platonically maintains that a certain pain, a certain greenish tint of yellow, a certain temperature, a certain sound, are the only reality.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "All men, in the vertiginous moment of coitus, are the same man.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "All men who repeat a line from Shakespeare \"are\" William Shakespeare.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Writing long books is a laborious and<bos> impoverishing act of foolishness: expanding in five hundred pages an idea that could be perfectly explained in a few minutes.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "A better procedure is to pretend that those books already exist and to offer a summary, a commentary.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "It seemed incredible to me that day without premonitions or symbols should be the one of my inexorable death.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I reflected that everything happens to a man precisely, precisely now.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Centuries of centuries and only in the present do things happen; countless men in the air, on the face of the earth and the sea, and all that really is happening is happening to me . . .", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I foresee that man will resign himself each day to more atrocious undertakings; soon there will be no one but warriors and brigands; I give them this counsel: The author of an atrocious undertaking ought to imagine that he has already accomplished it, ought to impose upon himself a future as irrevocable as the past.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I thought of a labyrinth of labyrinths, of one sinuous spreading labyrinth that would encompass the past and the future and in some way involve the stars.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I thought that a man can be an enemy of other men, of the moments of other men, but not of a country: not of fireflies, words, gardens, streams of water, sunsets.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "A labyrinth of symbols... An invisible labyrinth of time.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Ts'ui Pe must have said once: I am withdrawing to write a book. And another time: I am withdrawing to construct a labyrinth.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Every one imagined two works; to no one did it occur that the book and the maze were one and the same thing.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "I leave to the various futures (not to all) my garden of forking paths.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "In the work of Ts'ui Pên, all possible outcomes occur; each one is the point of departure for other forkings.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Sometimes, the paths of this labyrinth converge: for example, you arrive at this house, but in one of the possible pasts you are my enemy, in another, my friend.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Thus fought the heroes, tranquil their admirable hearts, violent their swords, resigned to kill and to die.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "In a riddle whose answer is chess, what is the only prohibited word?", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "This network of times which approached one another, forked, broke off, or were unaware of one another for centuries, embraces all possibilities of time.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Time forks perpetually toward innumerable futures. In one of them I am your enemy.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "My undertaking is not difficult, essentially... I should only have to be immortal to carry it out.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "There is no exercise of the intellect which is not, in the final analysis, useless.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "A philosophical doctrine begins as a plausible description of the universe; with the passage of the years it becomes a mere chapter — if not a paragraph or a name — in the history of philosophy.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Fame is a form—perhaps the worst form—of incomprehension.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Thinking, meditating, imagining are not anomalous acts – they are the normal respiration of the intelligence.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "To glorify the occasional exercise of that function, to treasure beyond price ancient and foreign thoughts, to recall with incredulous awe what some doctor universalis thought, is to confess our own languor, or our own barbarie.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "Every man should be capable of all ideas, and I believe that in the future he shall be.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "The truth is that we live out our lives putting off all that can be put off; perhaps we all know deep down that we are immortal and that, sooner or later, all men will do and know all things.", Author = "Jorge Luis Borges" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Luis_Borges", Text = "That history should have imitated history was already sufficiently marvellous; that history should imitate literature is inconceivable..", Author = "Jorge Luis Borges" },
        };
    }
}